// chartDataForExercise converts a slice of recent entries into the generic
// Chart props expected by components.Chart. Entries are grouped by calendar
// day and reduced to the heaviest weight of that day so the line reads as a
// PR-over-time view (rather than a noisy per-set series). Days are sorted
// ascending so the line runs left-to-right.
//
// The chart's title reports how many raw entries fed it (e.g. "Last 30 Sets")
// so the user can tell at a glance how much history the line represents. The
// chart component itself renders nothing when there are fewer than 2 labels.
func chartDataForExercise(entries []models.ExerciseEntry, exerciseName string) components.ChartProps {
	days := aggregateEntriesByDay(entries)
	labels, values := dayLabelsAndValues(days, "02 Jan")
	return components.ChartProps{
		ID:     "exercise-history-chart",
		Title:  fmt.Sprintf("Last %d Sets", len(entries)),
		Labels: labels,
		Datasets: []components.ChartDataset{
			{Label: exerciseName + " (kg)", Values: values},
		},
		// Hide the tick labels: the dates on x and the kg values on y would
		// overflow at this size. The y axis line and gridlines stay so the
		// line still has scale context, and tooltips still show exact values
		// on hover. The chart's own wrapper fills its parent; the view places
		// the chart in a sized inner wrapper inside the card.
		HideAxes: true,
	}
}

